C = dict(id='GL-17', title='Blockchain Health-Record Concepts', group='Digital and Technology', level=3,
 summary='Learn what a shared ledger can and cannot do for health records, and design a privacy-first concept that keeps patient data off the chain.',
 outcomes=['Explain blocks, hashes, consent and why health data needs special care.', 'Apply a hash and a simple ledger to a practice record.', 'Analyse use cases to decide where a ledger helps and where it does not.', 'Create a concept design that keeps patient data off-chain and consent on-chain.', 'Evaluate the design against privacy, safety, cost and rules.'],
 task='Produce a concept design and risk review for a health-record sharing idea that is privacy-first, with a working toy ledger on practice data.',
 cond='A computer, a free spreadsheet or small script tool, only invented practice records, a mentor and a peer circle. About 8 weeks part-time.',
 std='No real patient data used; design keeps personal data off the shared ledger; consent steps shown; cost and failure points listed; a health-privacy adviser or mentor signs off the concept as safe to discuss.',
 who='Health administrators, IT learners, students, policy assistants, technologists.', req='Basic computer skills. No coding needed.',
 safety='Concept learning only. Never use real health records. This is not medical or legal advice, and not a product for live use.',
 mods=[
 ('Health data is special', 'Health data can harm if it leaks.', ['Who sees what: patient, doctor, lab, insurer, family.', 'Rights: access, correction, consent, deletion where allowed.', 'Duties: keep records for a set time; keep them accurate.', 'Errors can harm a patient.'], 'A lab result wrongly filed under a name twin could lead to wrong treatment: accuracy matters as much as secrecy.', 'Map five people who touch a record.', 'Map shows what each may see.'),
 ('What a ledger is', 'A ledger is a shared list that is hard to change in secret.', ['Blocks hold entries; each block carries the fingerprint of the one before.', 'Change one old entry and every later fingerprint breaks.', 'Many copies are kept by different parties.', 'It records that something happened; it does not make it true.'], 'Three blocks A, B, C: B holds A\'s fingerprint. Edit A and B no longer matches: tampering shows.', 'Build a 5-row toy ledger in a spreadsheet.', 'Fingerprint column links rows; a change breaks the chain.'),
 ('Hashes and fingerprints', 'A hash turns any data into a short fixed code.', ['Same input gives same code; tiny change gives different code.', 'You cannot work backwards from the code.', 'Hash a file to prove it is unchanged.', 'Never hash small guessable values alone (like a phone number).'], 'A report hashed today and again in a year gives the same code: unchanged. A one-letter edit changes it completely.', 'Hash three practice files and one edited copy.', 'Codes compared and explained.'),
 ('Consent and identity', 'Patients should decide who sees what.', ['Consent record: who, what, why, when, until.', 'Withdraw consent as easily as giving it.', 'Use pseudonyms, not names, on a shared ledger.', 'Check who is who before granting access.'], 'Patient allows a clinic to see lab results for 30 days. Ledger entry: pseudonym, scope, expiry, no medical data.', 'Design a consent entry and a withdrawal entry.', 'Entries contain no personal health data.'),
 ('What goes on the chain', 'Keep patient data off a shared ledger.', ['Store records in protected systems; put only proofs and consents on the ledger.', 'A ledger cannot delete: never put personal data on it.', 'Think about access logs as evidence.', 'Costs and speed of writing entries.'], 'Record sits in a clinic system; ledger keeps its hash and the consent. Deletion of the record leaves a harmless hash.', 'Draw a two-layer design.', 'Diagram marks what is on and off the ledger.'),
 ('Use cases that work and do not', 'A ledger is not always the answer.', ['Helps: proof of unchanged records, consent trail, audit among many parties.', 'Does not help: speed, privacy by itself, fixing wrong data.', 'Ordinary databases are often better and cheaper.', 'Ask: do several parties distrust each other and need a shared truth?'], 'A single clinic with its own database does not need a ledger. Five hospitals sharing referral proofs might.', 'Score four ideas against five questions.', 'Scores justified; at least one idea rejected.'),
 ('Risks, rules and ethics', 'Think about harm first.', ['Privacy law, health law and cross-border limits.', 'Security of keys and devices.', 'Fairness: who is left out if they lack a phone?', 'What happens when something goes wrong?'], 'A patient loses the key to their identity: design a recovery route through a trusted clinic.', 'Write a risk table with eight rows.', 'Each risk has a control.'),
 ('Present the concept', 'Explain it to a decision maker in plain words.', ['One page: problem, idea, what is on and off the ledger, risks, cost.', 'Show the toy ledger working.', 'State clearly what it cannot do.', 'Plan 90 days: consult adviser, test with fake data.'], 'Summary: "We store proofs and consents only; records stay in clinics. Cost is small; the main risk is key loss."', 'Present to a peer circle and a mentor.', 'Mentor confirms no real data and no live-use claims.')],
 quiz=[('What links blocks together?', 'Each block holds the fingerprint of the previous block.'), ('Can you reverse a hash?', 'No.'), ('Does a ledger prove something is true?', 'No; it proves it was recorded and unchanged.'), ('What should never be on a shared ledger?', 'Personal health data.'), ('What does a consent entry hold?', 'Who, what, why, when and until.'), ('Why use pseudonyms?', 'To avoid names on a shared list.'), ('When is an ordinary database better?', 'When one party controls the data and trust is not an issue.'), ('Name one risk of lost keys.', 'A patient may lose access; need a recovery route.'), ('Why concept only?', 'Live health systems need legal, clinical and security approval.'), ('What happens if you change an old block?', 'Later fingerprints no longer match.')],
 rubric=[('Understanding', 'Explains blocks, hashes, consent', 'Explains limits with examples'), ('Toy ledger', 'Works and detects change', 'Documented with tests'), ('Privacy design', 'No personal data on chain', 'Recovery and withdrawal covered'), ('Risk review', 'Eight risks with controls', 'Adviser comments addressed'), ('Communication', 'One-page concept', 'Non-technical reader understands it')],
 jobs=[('Health information assistant', 'Supports records teams'), ('Digital health analyst (junior)', 'Reviews concepts and risks'), ('Policy support assistant', 'Explains technology to decision makers'), ('IT project assistant', 'Supports pilots with fake data')],
 next='Privacy Protection Practice; Wallet Payment Solutions; Online Currency Exchange Concepts.',
 local='Health and privacy law differ strongly by place and often limit what can be shared: always consult the local health-data authority.',
 evidence='Your evidence: five-person access map, toy ledger, hash comparison, consent entries, two-layer diagram, use-case scores, risk table and one-page concept.',
 ladder=[('Basics of records', 'Explain why records matter. Notes: talk about a clinic visit.'), ('Awareness', 'Know hashes and ledgers. Notes: toy ledger demo.'), ('Foundation', 'This course. Notes: concept and risks.'), ('Practitioner', 'Support a pilot with fake data. Notes: test plans.'), ('Specialist', 'Design with standards. Notes: add health data standards.'), ('Advanced', 'Lead governance. Notes: ethics board and audits.'), ('Super expert', 'Set method and teach teachers. Notes: review laws yearly.')])
